-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 15 recettes, 2 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', 'Wikimedia Commons', ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · Wikimedia Commons',
        true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"lovo-fidji","country":"FJ","original":"Lovo","title":"Lovo fidjien (viandes et tubercules cuits au four de terre)","en":"Fijian lovo (earth oven feast)","es":"Lovo fiyiano (festín en horno de tierra)","desc":"Viandes, poisson, taro et manioc enveloppés de feuilles et cuits sur des pierres chaudes enterrées; adaptation en cocotte au four.","cat":"Plat principal","diff":"medium","prep":40,"cook":180,"serv":8,"ing":[["Épaule de porc ou agneau",1.2,"kg",null],["Poulet",1,"kg","en morceaux"],["Taro",600,"g",null],["Manioc",600,"g",null],["Patates douces",600,"g",null],["Lait de coco",400,"ml",null],["Oignon",1,null,null],["Feuilles de bananier",8,null,null],["Sel",2,"c. à thé",null]],"steps":["Saler les viandes et les envelopper avec les tubercules dans des feuilles de bananier.","Placer les paquets dans une grande cocotte avec 250 ml d’eau.","Couvrir hermétiquement et cuire 3 heures à 160 °C (ou au four de terre).","Chauffer le lait de coco avec l’oignon et du sel pour la sauce.","Servir tous les éléments ensemble avec la sauce coco."],"photo":null},{"slug":"vakalolo","country":"FJ","original":"Vakalolo","title":"Vakalolo fidjien (pudding de manioc au caramel de coco)","en":"Fijian vakalolo (cassava pudding with coconut caramel)","es":"Vakalolo fiyiano (pudín de yuca con caramelo de coco)","desc":"Petits paquets de manioc râpé cuits en feuille, nappés d’une sauce caramel au lait de coco (lolo).","cat":"Dessert","diff":"medium","prep":30,"cook":60,"serv":8,"ing":[["Manioc",800,"g","râpé finement"],["Sucre roux",150,"g",null],["Lait de coco",400,"ml",null],["Feuilles de bananier",8,null,null],["Sel",1,"pincée",null]],"steps":["Mélanger le manioc avec 50 g de sucre et le sel.","Envelopper en petits paquets de feuilles de bananier.","Cuire 45 minutes à la vapeur.","Caraméliser le reste du sucre, ajouter le lait de coco et réduire en sauce épaisse.","Servir les paquets ouverts nappés de caramel de coco."],"photo":null},{"slug":"fijian-chicken-curry","country":"FJ","original":"Curry de poulet indo-fidjien","title":"Curry de poulet indo-fidjien (masala et pommes de terre)","en":"Indo-Fijian chicken curry","es":"Curry de pollo indo-fiyiano","desc":"Curry de poulet des communautés indo-fidjiennes, au masala grillé, feuilles de curry et pommes de terre, servi avec roti ou riz.","cat":"Plat principal","diff":"easy","prep":20,"cook":45,"serv":6,"ing":[["Poulet",1.2,"kg","en morceaux"],["Masala fidjien ou curry",3,"c. à soupe",null],["Oignon",2,null,"émincés"],["Ail et gingembre",2,"c. à soupe","pilés"],["Feuilles de curry",10,null,null],["Tomates",2,null,"en dés"],["Pommes de terre",3,null,"en cubes"],["Graines de moutarde et cumin",1,"c. à thé",null],["Huile",4,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Faire éclater moutarde et cumin dans l’huile, ajouter feuilles de curry et oignons.","Ajouter ail, gingembre et masala délayé; faire griller 2 minutes.","Ajouter le poulet et les tomates; cuire 10 minutes.","Ajouter pommes de terre et 400 ml d’eau; mijoter 25 minutes.","Saler et servir avec roti."],"photo":null},{"slug":"aigir-east-new-britain","country":"PG","place":{"slug":"pg-east-new-britain","name":"Nouvelle-Bretagne orientale","type":"region","lat":-4.6,"lng":152,"summary":"Province insulaire (Rabaul, peuple tolai), connue pour l’aigir cuit aux pierres chaudes."},"original":"Aigir","title":"Aigir de Nouvelle-Bretagne (poulet et légumes au lait de coco aux pierres chaudes)","en":"East New Britain aigir (coconut chicken and vegetables cooked with hot stones)","es":"Aigir de Nueva Bretaña (pollo y verduras con coco)","desc":"Plat tolai : poulet, taro, patate douce et feuilles cuits dans le lait de coco avec des pierres chauffées, enveloppés de feuilles de bananier.","cat":"Plat principal","diff":"medium","prep":40,"cook":90,"serv":6,"ing":[["Poulet",1.2,"kg","en morceaux"],["Taro",500,"g",null],["Patate douce",500,"g",null],["Banane à cuire",2,null,null],["Feuilles vertes (aibika ou épinards)",300,"g",null],["Lait de coco",600,"ml",null],["Oignon",1,null,null],["Sel",2,"c. à thé",null],["Feuilles de bananier",6,null,null]],"steps":["Tapisser une cocotte de feuilles de bananier.","Disposer poulet, tubercules, banane et feuilles en couches; saler.","Verser le lait de coco avec l’oignon émincé.","Refermer les feuilles, couvrir et cuire 1 h 30 à 170 °C.","Servir dans les feuilles."],"photo":null},{"slug":"kaukau-coco-png","country":"PG","original":"Kaukau","title":"Kaukau de Papouasie (patates douces au lait de coco)","en":"Papua New Guinean kaukau (sweet potato in coconut milk)","es":"Kaukau de Papúa (boniato con leche de coco)","desc":"Patates douces des Hautes-Terres mijotées dans le lait de coco avec feuilles vertes et oignon, aliment de base de la Papouasie–Nouvelle-Guinée.","cat":"Accompagnement","diff":"easy","prep":15,"cook":30,"serv":4,"ing":[["Patates douces",800,"g","en morceaux"],["Lait de coco",400,"ml",null],["Oignon",1,null,"émincé"],["Épinards ou feuilles de patate douce",200,"g",null],["Gingembre",15,"g","râpé"],["Sel",1,"c. à thé",null]],"steps":["Porter le lait de coco à frémissement avec oignon et gingembre.","Ajouter les patates douces et cuire 20 minutes.","Ajouter les feuilles et cuire 5 minutes.","Saler et servir."],"photo":null},{"slug":"saksak","country":"PG","place":"sepik","original":"Saksak","title":"Saksak du Sepik (boulettes de sagou à la banane et coco)","en":"Sepik saksak (sago and banana dumplings)","es":"Saksak del Sepik (bolitas de sagú con plátano)","desc":"Boulettes de sagou et de banane mûre cuites dans le lait de coco, préparation traditionnelle des régions du fleuve Sepik.","cat":"Dessert","diff":"easy","prep":20,"cook":30,"serv":6,"ing":[["Farine de sagou",300,"g",null],["Bananes mûres",3,null,"écrasées"],["Lait de coco",400,"ml",null],["Sucre",2,"c. à soupe","facultatif"],["Feuilles de bananier",6,null,null]],"steps":["Mélanger sagou et bananes écrasées avec un peu d’eau en pâte ferme.","Former des boulettes et les envelopper de feuilles de bananier.","Les pocher 20 minutes dans le lait de coco frémissant.","Sucrer le lait de coco si désiré.","Servir les boulettes arrosées de lait de coco."],"photo":null},{"slug":"tuluk-vanuatu","country":"VU","original":"Tuluk","title":"Tuluk du Vanuatu (pâte de manioc farcie au porc en feuille)","en":"Vanuatu tuluk (cassava parcels with pork)","es":"Tuluk de Vanuatu (paquetes de yuca rellenos de cerdo)","desc":"Pâte de manioc râpé enveloppant du porc ou du bœuf haché au lait de coco, cuite en feuille de bananier, vendue sur les marchés de Port-Vila.","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":60,"serv":6,"ing":[["Manioc",1,"kg","râpé finement"],["Porc haché",400,"g",null],["Lait de coco",200,"ml",null],["Oignon",1,null,"haché"],["Gingembre",15,"g","râpé"],["Sel",1.5,"c. à thé",null],["Feuilles de bananier",6,null,null]],"steps":["Presser le manioc râpé pour retirer l’excès d’eau et le saler.","Mélanger le porc avec l’oignon, le gingembre, le lait de coco et du sel.","Étaler une couche de manioc sur chaque feuille, déposer la farce et recouvrir de manioc.","Refermer les paquets.","Cuire 1 heure à la vapeur ou au four à 180 °C."],"photo":null},{"slug":"simboro","country":"VU","original":"Simboro","title":"Simboro du Vanuatu (rouleaux de feuilles farcis au manioc et coco)","en":"Vanuatu simboro (leaf rolls with cassava and coconut)","es":"Simboro de Vanuatu (rollos de hojas con yuca y coco)","desc":"Manioc ou banane râpés roulés dans des feuilles d’aibika et cuits dans la crème de coco.","cat":"Accompagnement","diff":"medium","prep":30,"cook":30,"serv":4,"ing":[["Manioc ou banane verte",500,"g","râpé"],["Feuilles d’aibika ou de blette",16,null,null],["Crème de coco",400,"ml",null],["Oignon",1,null,"haché"],["Sel",1,"c. à thé",null]],"steps":["Saler le manioc râpé.","Déposer une cuillerée sur chaque feuille et rouler en cigare.","Ranger les rouleaux serrés dans une casserole.","Couvrir de crème de coco et d’oignon.","Cuire 25 à 30 minutes à couvert à feu doux."],"photo":null},{"slug":"nalot","country":"VU","original":"Nalot","title":"Nalot du Vanuatu (taro ou banane pilés au lait de coco)","en":"Vanuatu nalot (pounded taro or banana with coconut)","es":"Nalot de Vanuatu (taro o plátano machacado con coco)","desc":"Taro, igname ou banane cuits sur la braise puis pilés et nappés de crème de coco, plat cérémoniel du Vanuatu.","cat":"Accompagnement","diff":"easy","prep":15,"cook":45,"serv":4,"ing":[["Taro ou bananes à cuire",800,"g",null],["Crème de coco",250,"ml",null],["Sel",0.5,"c. à thé",null]],"steps":["Cuire le taro ou les bananes au four ou sur la braise dans leur peau 40 minutes.","Les peler encore chauds.","Les piler au mortier ou les écraser en pâte lisse.","Façonner en galettes.","Napper de crème de coco salée et servir."],"photo":null},{"slug":"sapasui","country":"WS","original":"Sapasui","title":"Sapasui samoan (vermicelles sautés au bœuf et soja)","en":"Samoan sapasui (chop suey)","es":"Sapasui samoano (fideos salteados con ternera)","desc":"Version samoane du chop suey : vermicelles de haricot mungo sautés avec bœuf ou poulet, gingembre et sauce soja, incontournable des fêtes.","cat":"Plat principal","diff":"easy","prep":20,"cook":25,"serv":6,"ing":[["Vermicelles de haricot mungo",250,"g","trempés"],["Bœuf ou poulet",500,"g","en lanières"],["Oignon",1,null,"émincé"],["Gingembre",20,"g","râpé"],["Ail",3,"gousses",null],["Sauce soja",100,"ml",null],["Carottes et chou",300,"g","en julienne"],["Huile",3,"c. à soupe",null]],"steps":["Faire revenir oignon, ail et gingembre dans l’huile.","Ajouter la viande et la saisir.","Ajouter les légumes et la moitié de la sauce soja.","Ajouter les vermicelles égouttés et le reste de sauce avec un peu d’eau.","Sauter jusqu’à absorption et servir."],"photo":null},{"slug":"panipopo","country":"WS","original":"Panipopo","title":"Panipopo samoans (petits pains briochés au caramel de coco)","en":"Samoan panipopo (coconut caramel buns)","es":"Panipopo samoanos (bollos en caramelo de coco)","desc":"Petits pains briochés cuits dans une sauce sucrée au lait de coco qui caramélise au fond du plat.","cat":"Dessert","diff":"medium","prep":40,"cook":30,"serv":12,"ing":[["Farine",500,"g",null],["Lait tiède",250,"ml",null],["Levure sèche",7,"g",null],["Sucre",60,"g","pour la pâte"],["Beurre",50,"g",null],["Lait de coco",400,"ml",null],["Sucre (sauce)",150,"g",null]],"steps":["Pétrir farine, lait, levure, sucre et beurre; laisser lever 1 heure.","Former 12 boules et les ranger dans un plat; laisser lever 30 minutes.","Chauffer lait de coco et sucre jusqu’à dissolution.","Verser la sauce autour des pains.","Cuire 25 à 30 minutes à 180 °C et servir en arrosant de sauce."],"photo":null},{"slug":"koko-alaisa","country":"WS","original":"Koko alaisa","title":"Koko alaisa samoan (riz au cacao de Samoa)","en":"Samoan koko alaisa (cocoa rice)","es":"Koko alaisa samoano (arroz con cacao)","desc":"Riz cuit dans une boisson de cacao samoan (koko Samoa) sucrée, parfois à l’orange ou au lait de coco, servi au petit-déjeuner.","cat":"Petit-déjeuner","diff":"easy","prep":10,"cook":30,"serv":4,"ing":[["Riz",200,"g",null],["Cacao pur (koko Samoa) ou cacao non sucré",60,"g",null],["Eau",1,"l",null],["Sucre",100,"g",null],["Feuilles d’oranger ou zeste d’orange",2,null,null],["Lait de coco",200,"ml","facultatif"]],"steps":["Porter l’eau à ébullition avec le cacao et le zeste.","Ajouter le riz et cuire 20 minutes en remuant.","Ajouter le sucre et le lait de coco.","Cuire 5 minutes jusqu’à consistance de porridge.","Servir chaud."],"photo":null},{"slug":"hangi","country":"NZ","original":"Hāngī","title":"Hāngī māori (viandes et légumes cuits dans un four de terre)","en":"Māori hāngī (earth oven feast)","es":"Hāngī maorí (festín en horno de tierra)","desc":"Agneau, porc, poulet, kūmara et courge cuits dans un four creusé dans le sol sur des pierres chaudes; adaptation au four maison.","cat":"Plat principal","diff":"medium","prep":40,"cook":180,"serv":8,"ing":[["Épaule d’agneau",1.2,"kg",null],["Poitrine de porc",800,"g",null],["Poulet",1,null,"en morceaux"],["Kūmara (patates douces)",1,"kg",null],["Courge",800,"g",null],["Pommes de terre",800,"g",null],["Farce (stuffing) au pain",400,"g","facultatif"],["Sel et poivre",2,"c. à thé",null]],"steps":["Saler et poivrer les viandes.","Disposer viandes et légumes dans des paniers ou une grande rôtissoire, sur un lit de chou ou de feuilles.","Couvrir de linges humides et d’aluminium.","Cuire 3 heures à 160 °C (ou 3 à 4 heures dans le hāngī).","Servir tout ensemble."],"photo":null},{"slug":"whitebait-fritters","country":"NZ","place":{"slug":"nz-west-coast","name":"Côte Ouest (Nouvelle-Zélande)","type":"region","lat":-42.45,"lng":171.21,"summary":"Région sauvage de l’île du Sud, capitale de la pêche au whitebait."},"original":"Whitebait fritters","title":"Whitebait fritters de la Côte Ouest (galettes d’alevins à l’œuf)","en":"West Coast whitebait fritters","es":"Tortitas de chanquetes de la Costa Oeste","desc":"Galettes d’alevins liées à l’œuf, dorées au beurre et servies sur du pain beurré avec citron, spécialité printanière de la Côte Ouest.","cat":"Poisson","diff":"easy","prep":10,"cook":10,"serv":4,"ing":[["Whitebait (alevins) ou petits poissons",400,"g",null],["Œufs",3,null,null],["Farine",2,"c. à soupe","facultatif"],["Beurre",40,"g",null],["Pain de mie",4,"tranches","beurrées"],["Citron",1,null,null],["Sel et poivre",1,"c. à thé",null]],"steps":["Battre les œufs avec la farine, le sel et le poivre.","Incorporer délicatement le whitebait.","Déposer des cuillerées dans le beurre mousseux.","Cuire 1 à 2 minutes par face.","Servir sur pain beurré avec du citron."],"photo":null},{"slug":"damper-australien","country":"AU","original":"Damper","title":"Damper australien (pain de brousse cuit sous la cendre)","en":"Australian damper (bush bread)","es":"Damper australiano (pan del bush)","desc":"Pain rustique sans levure, traditionnellement cuit dans les braises d’un feu de camp par les stockmen, servi avec beurre et golden syrup.","cat":"Pain","diff":"easy","prep":10,"cook":35,"serv":6,"ing":[["Farine avec levure incorporée",450,"g",null],["Beurre",60,"g",null],["Lait",250,"ml",null],["Sel",1,"c. à thé",null],["Golden syrup ou miel",4,"c. à soupe","pour servir"]],"steps":["Sabler la farine, le sel et le beurre.","Ajouter le lait et former une boule sans trop pétrir.","Aplatir en disque et entailler le dessus en croix.","Cuire 30 à 35 minutes à 200 °C (ou en cocotte dans les braises).","Servir chaud avec beurre et golden syrup."],"photo":null}]$batch$::jsonb);
